    end
  end

  # The public link comes from a Cloudflare quick tunnel.
  depends_on "cloudflared"

  def install
    bin.install "tether"
  end

  def caveats
    <<~EOS
      Start Tether in the background (it also starts again at login):
        tether start

      On a new machine it first asks how to run it: self-host (the
      default, press Enter) or Tether host (a fixed address on your
      Tether account; tether start --hosted skips the question).

      It prints a link and a QR code that open the Tether app for this
      machine: https://tether.ahabyte.com

      After `brew upgrade tether`, run `tether restart`.
      Other commands: tether status | logs | stop | help
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/tether version")
    assert_match "tether start", shell_output("#{bin}/tether help 2>&1")
  end
end
